pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Reverter {
    fallback() external payable {
        revert();
    }
}

contract InvMutTest is Test {
    C c;
    Reverter reverter;
    function setUp() public { 
        c = new C(); 
        reverter = new Reverter();
    }
    function testRegression_property() public {
        // Owner calls sendMoney with a reverter contract as target, value 1 wei
        // Reference: fallback executes first (increments depositsCount), then reverts
        // Mutant: fallback does nothing (depositsCount stays 0), then reverts
        bool success;
        try c.sendMoney(address(reverter), 1) {
            success = true;
        } catch {
            success = false;
        }
        // Both revert because Reverter reverts, so success is false
        // But depositsCount differs: reference increments, mutant doesn't
        // Reference depositsCount == 1, mutant depositsCount == 0
        assertTrue(c.depositsCount() == 1);
    }
}

